            }

            string orderByClause = orderByClauses.Any() ? "ORDER BY " + string.Join(", ", orderByClauses) : "ORDER BY integrity_finding_pk";

            return $@"SELECT e.* FROM (SELECT * FROM [analysis].[integrity_finding]  ) e {whereClause} {orderByClause}
                  OFFSET @Offset ROWS FETCH NEXT @PageSize ROWS ONLY";
